struct Shape {
    Shape() : sides(0) {}
    explicit Shape(int n) : sides(n) {}
    ~Shape() {}
    virtual int area() const { return 0; }
    int sides;
};

struct Square : Shape {
    Square() : Shape(4) {}
    int area() const override { return 1; }
};

template <typename T> struct Box { T value; };
template <> struct Box<bool> { bool flag; };
Box(const char*) -> Box<bool>;
template <typename T> Box(T*, int) -> Box<T*>;

template <typename T> T pick(T value) { return value; }
template <> int pick<int>(int value) { return value + 1; }

int main() {
    Shape s(3);
    Square q;
    Box<int> b{1};
    Box<bool> f{true};
    return s.area() + q.area() + b.value + f.flag + pick(1) + pick<long>(2);
}

